// Validates the incoming request and builds the URL of the optimized file.
//
// This test workflow uses images.weserv.nl — a free, no-signup image CDN — to do
// the real resize/convert work, so the whole flow runs without credentials.
// Swap this one line for your own pipeline (Edit Image node, Cloudinary, S3…)
// when you move to production; nothing else in the workflow needs to change.

const body = $input.first().json.body || {};

const imageUrl = String(body.image_url || '').trim();
if (!/^https?:\/\//i.test(imageUrl)) {
  throw new Error('image_url must be an http(s) URL');
}

const requested = String(body.output_format || 'webp').toLowerCase();
const outputFormat = requested === 'jpeg' ? 'jpg' : ['png', 'jpg', 'webp'].includes(requested) ? requested : 'webp';

// w=1600 caps the long edge, q=82 is a sane quality floor, &we asks weserv to
// skip enlargement when the source is already smaller.
const optimizedUrl =
  'https://images.weserv.nl/?url=' +
  encodeURIComponent(imageUrl) +
  '&output=' + outputFormat +
  '&q=82&w=1600&we';

return [
  {
    json: {
      image_url: imageUrl,
      output_format: outputFormat,
      use_ai_analysis: body.use_ai_analysis !== false,
      brand: body.brand || {},
      optimized_url: optimizedUrl,
    },
  },
];

// Build the exact JSON the AI Image SEO Optimizer front end expects.
// Measures both downloaded files, then writes the SEO copy from the brand
// fields. Swap this node for an AI Agent when you want model-written copy.

/** Reads pixel dimensions straight from the file header (JPEG / PNG / WebP / GIF). */
function readDimensions(buffer) {
  if (!buffer || buffer.length < 32) return { width: null, height: null };

  if (buffer.readUInt32BE(0) === 0x89504e47) {
    return { width: buffer.readUInt32BE(16), height: buffer.readUInt32BE(20) };
  }

  if (buffer.toString('ascii', 0, 3) === 'GIF') {
    return { width: buffer.readUInt16LE(6), height: buffer.readUInt16LE(8) };
  }

  if (buffer.toString('ascii', 0, 4) === 'RIFF' && buffer.toString('ascii', 8, 12) === 'WEBP') {
    const chunk = buffer.toString('ascii', 12, 16);
    if (chunk === 'VP8 ') {
      return { width: buffer.readUInt16LE(26) & 0x3fff, height: buffer.readUInt16LE(28) & 0x3fff };
    }
    if (chunk === 'VP8L') {
      const bits = buffer.readUInt32LE(21);
      return { width: (bits & 0x3fff) + 1, height: ((bits >> 14) & 0x3fff) + 1 };
    }
    if (chunk === 'VP8X') {
      return {
        width: 1 + (buffer[24] | (buffer[25] << 8) | (buffer[26] << 16)),
        height: 1 + (buffer[27] | (buffer[28] << 8) | (buffer[29] << 16)),
      };
    }
    return { width: null, height: null };
  }

  if (buffer[0] === 0xff && buffer[1] === 0xd8) {
    let offset = 2;
    while (offset + 9 < buffer.length) {
      if (buffer[offset] !== 0xff) {
        offset += 1;
        continue;
      }
      const marker = buffer[offset + 1];
      if (marker >= 0xc0 && marker <= 0xcf && marker !== 0xc4 && marker !== 0xc8 && marker !== 0xcc) {
        return { height: buffer.readUInt16BE(offset + 5), width: buffer.readUInt16BE(offset + 7) };
      }
      offset += 2 + buffer.readUInt16BE(offset + 2);
    }
  }

  return { width: null, height: null };
}

function readFormat(buffer, fallback) {
  if (!buffer || buffer.length < 12) return fallback;
  if (buffer.readUInt32BE(0) === 0x89504e47) return 'png';
  if (buffer[0] === 0xff && buffer[1] === 0xd8) return 'jpg';
  if (buffer.toString('ascii', 0, 3) === 'GIF') return 'gif';
  if (buffer.toString('ascii', 0, 4) === 'RIFF' && buffer.toString('ascii', 8, 12) === 'WEBP') {
    return 'webp';
  }
  return fallback;
}

/** n8n keeps small binaries in memory as base64; fall back to the size label. */
function toBuffer(binary) {
  if (binary && typeof binary.data === 'string' && binary.data.length > 0) {
    try {
      return Buffer.from(binary.data, 'base64');
    } catch (error) {
      return null;
    }
  }
  return null;
}

function parseSizeLabel(label) {
  const text = String(label || '').replace(/,/g, '');
  const match = text.match(/-?\d+(\.\d+)?/);
  if (!match) return null;
  const value = Number(match[0]);
  if (/\bkb\b/i.test(text)) return Math.round(value * 1024);
  if (/\bmb\b/i.test(text)) return Math.round(value * 1024 * 1024);
  return Math.round(value);
}

function slugify(value) {
  return String(value || '')
    .toLowerCase()
    .normalize('NFKD')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 70);
}

function titleCase(value) {
  return String(value || '')
    .split(/\s+/)
    .filter(Boolean)
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
    .join(' ');
}

function toKeywords(value) {
  if (Array.isArray(value)) return value.map((item) => String(item).trim()).filter(Boolean);
  return String(value || '')
    .split(/[,\n;|]/)
    .map((item) => item.trim())
    .filter(Boolean);
}

/** Trims to a whole word so the copy never ends mid-syllable. */
function clamp(text, limit) {
  const clean = String(text || '').replace(/\s+/g, ' ').trim();
  if (clean.length <= limit) return clean;
  return clean.slice(0, limit).replace(/\s+\S*$/, '') + '…';
}

function describeShape(width, height) {
  if (!width || !height) return 'image';
  const ratio = width / height;
  if (ratio > 1.25) return 'landscape photo';
  if (ratio < 0.8) return 'portrait photo';
  return 'square image';
}

function buildSeo(brand, format, useAi, optimized) {
  const primary = brand.primary_keyword || brand.company_name || 'optimized image';
  const secondary = toKeywords(brand.secondary_keywords);
  const company = brand.company_name || '';
  const shape = describeShape(optimized.width, optimized.height);

  // With analysis on, the copy folds in what we measured from the file itself.
  // With it off, it is written from the brand fields alone.
  const visual = useAi
    ? 'A ' + shape + (optimized.width ? ' at ' + optimized.width + '×' + optimized.height : '') +
      ' showing ' + primary
    : titleCase(primary);

  const audience = brand.target_audience ? ' for ' + brand.target_audience : '';
  const market = brand.target_market ? ' in ' + brand.target_market : '';
  const industry = brand.industry ? ' ' + brand.industry : '';

  const nameParts = [slugify(primary), slugify(secondary[0] || ''), slugify(company)].filter(Boolean);
  const filename = [...new Set(nameParts)].join('-').slice(0, 80) || 'optimized-image';

  return {
    filename: filename + '.' + format,
    alt_text: clamp(visual + (company ? ' from ' + company : '') + audience, 125),
    title: clamp(company ? titleCase(primary) + ' | ' + company : titleCase(primary), 60),
    caption: clamp(
      brand.brand_description
        ? brand.brand_description.split(/(?<=[.!?])\s/)[0]
        : titleCase(primary) + market + '.',
      160,
    ),
    description: clamp(
      visual + '.' + (industry ? ' Part of' + industry + ' range' : '') +
        (company ? ' by ' + company : '') + market + audience + '. ' +
        (brand.brand_description || ''),
      300,
    ),
    primary_keyword: primary,
    secondary_keywords: secondary,
  };
}

// --- wire it up -------------------------------------------------------------

const request = $('Prepare request').first().json;
const brand = request.brand || {};
const format = request.output_format;
const useAi = request.use_ai_analysis;

const originalBinary = ($('Download original').first().binary || {}).data;
const optimizedBinary = ($('Download optimized').first().binary || {}).data;

const originalBuffer = toBuffer(originalBinary);
const optimizedBuffer = toBuffer(optimizedBinary);

const original = {
  url: request.image_url,
  size_bytes: originalBuffer ? originalBuffer.length : parseSizeLabel(originalBinary && originalBinary.fileSize),
  ...readDimensions(originalBuffer),
  format: readFormat(originalBuffer, null),
};

const optimized = {
  url: request.optimized_url,
  size_bytes: optimizedBuffer ? optimizedBuffer.length : parseSizeLabel(optimizedBinary && optimizedBinary.fileSize),
  ...readDimensions(optimizedBuffer),
  format: readFormat(optimizedBuffer, format),
};

const reduction =
  original.size_bytes && optimized.size_bytes
    ? Math.round(((original.size_bytes - optimized.size_bytes) / original.size_bytes) * 1000) / 10
    : null;

return [
  {
    json: {
      original,
      optimized,
      size_reduction_percent: reduction,
      use_ai_analysis: useAi,
      seo: buildSeo(brand, format, useAi, optimized),
    },
  },
];
